const ROAD = 1;

// CONTRACT for markReachableNodes(graph, node, visited):
//     when this call returns, `node` and every node you can reach
//     from `node` by following one-way roads is in the visited set.
const markReachableNodes = (graph, node, visited) => {
    // Base case
    if (visited.has(node)) return;

    // Process node
    visited.add(node);

    // Recurse on neighbors
    for (
        let potentialNeighbor = 0;
        potentialNeighbor < graph.length;
        potentialNeighbor++
    ) {
        const isNeighbor = graph[node][potentialNeighbor] === ROAD;

        if (!isNeighbor) continue;

        // Directed graphs can still contain cycles (like 0 -> 1 -> 0),
        // so the visited check above is what stops infinite recursion.
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `potentialNeighbor` and
        // everything reachable from it is in visited. Trust it, do not
        // trace it. This function already put `node` into visited, and
        // each neighbor's contract covers everything past that neighbor
        // — together, that is this function's full contract, kept.
        markReachableNodes(graph, potentialNeighbor, visited);
    }
};

const transitiveClosure = (graph) => {
    const numNodes = graph.length;

    const reach = [];

    for (let startNode = 0; startNode < numNodes; startNode++) {
        // Each row of the answer is one full DFS, so every start node
        // gets its own fresh visited set.
        const visited = new Set();
        // The recursive leap of faith: trust the contract. When this
        // call returns, `startNode` and every node reachable from it
        // is in visited — nothing more, nothing less. We do not trace
        // inside; we just read the finished visited set and turn it
        // into one row of 1s and 0s.
        markReachableNodes(graph, startNode, visited);

        const reachRow = [];
        for (let targetNode = 0; targetNode < numNodes; targetNode++) {
            const isReachable = visited.has(targetNode);
            reachRow.push(isReachable ? 1 : 0);
        }

        reach.push(reachRow);
    }

    return reach;
};

const X_COORDINATE = 0;
const Y_COORDINATE = 1;
const POWER = 2;

const buildTransmissionGraph = (cows) => {
    const graph = {};

    for (let cowIndex = 0; cowIndex < cows.length; cowIndex++) {
        graph[cowIndex] = [];
    }

    for (let senderIndex = 0; senderIndex < cows.length; senderIndex++) {
        for (let receiverIndex = 0; receiverIndex < cows.length; receiverIndex++) {
            if (senderIndex === receiverIndex) continue;

            const sender = cows[senderIndex];
            const receiver = cows[receiverIndex];

            const xDifference = sender[X_COORDINATE] - receiver[X_COORDINATE];
            const yDifference = sender[Y_COORDINATE] - receiver[Y_COORDINATE];
            const squaredDistance =
                xDifference * xDifference + yDifference * yDifference;

            // Comparing squared values avoids Math.sqrt entirely.
            // Only the SENDER's power matters, so this edge is one-way:
            // a strong cow may reach a weak cow that cannot answer back.
            const senderPower = sender[POWER];
            const canTransmit = squaredDistance <= senderPower * senderPower;

            if (!canTransmit) continue;

            graph[senderIndex].push(receiverIndex);
        }
    }

    return graph;
};

// CONTRACT for markReachableCows(graph, cow, visited):
//     when this call returns, `cow` and every cow her broadcast can
//     reach through any chain of one-way transmissions is in the
//     visited set.
const markReachableCows = (graph, cow, visited) => {
    // Base case
    if (visited.has(cow)) return;

    // Process node
    visited.add(cow);

    // Recurse on neighbors
    const neighbors = graph[cow];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and every
        // cow reachable from `neighbor` is in visited. Trust it, do
        // not trace it. This function already put `cow` into visited,
        // and each neighbor's contract covers all the cows past that
        // neighbor — together, that is this function's full contract,
        // kept.
        markReachableCows(graph, neighbor, visited);
    }
};

const maxBroadcast = (cows) => {
    const graph = buildTransmissionGraph(cows);

    let maxCowsReached = 0;

    for (let startCow = 0; startCow < cows.length; startCow++) {
        // Edges are one-way, so each starting cow can reach a different
        // set of cows and needs her own fresh visited set.
        const visited = new Set();
        // The recursive leap of faith: trust the contract. When this
        // call returns, `startCow` and every cow she can reach is in
        // visited — so visited.size IS her broadcast count. We do not
        // trace inside; we just take the size and keep the biggest.
        markReachableCows(graph, startCow, visited);

        maxCowsReached = Math.max(maxCowsReached, visited.size);
    }

    return maxCowsReached;
};

const countSharedDistinctValues = (valueSetOne, valueSetTwo) => {
    let sharedCount = 0;

    for (const value of valueSetOne) {
        if (valueSetTwo.has(value)) sharedCount++;
    }

    return sharedCount;
};

const buildPropertiesGraph = (properties, minSharedValues) => {
    const graph = {};

    for (let nodeIndex = 0; nodeIndex < properties.length; nodeIndex++) {
        graph[nodeIndex] = [];
    }

    // Turning each row into a Set up front means intersect counts
    // DISTINCT values (duplicates collapse) and lookups are fast.
    const distinctValueSets = properties.map((row) => new Set(row));

    // n <= 100, so checking every pair of rows is perfectly fine.
    for (let nodeOne = 0; nodeOne < properties.length; nodeOne++) {
        for (let nodeTwo = nodeOne + 1; nodeTwo < properties.length; nodeTwo++) {
            const sharedValues = countSharedDistinctValues(
                distinctValueSets[nodeOne],
                distinctValueSets[nodeTwo],
            );

            if (sharedValues < minSharedValues) continue;

            graph[nodeOne].push(nodeTwo);
            graph[nodeTwo].push(nodeOne);
        }
    }

    return graph;
};

// CONTRACT for markComponentAsVisited(graph, node, visited):
//     when this call returns, `node` and every node reachable
//     from `node` is in the visited set.
const markComponentAsVisited = (graph, node, visited) => {
    // Base case
    if (visited.has(node)) return;

    // Process node
    visited.add(node);

    // Recurse on neighbors
    const neighbors = graph[node];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and everything
        // reachable from it is in visited. Trust it, do not trace it.
        // This function already put `node` into visited, and each
        // neighbor's contract puts everything reachable from that
        // neighbor into visited — together, that is this function's
        // full contract, kept.
        markComponentAsVisited(graph, neighbor, visited);
    }
};

const numberOfComponents = (properties, k) => {
    const graph = buildPropertiesGraph(properties, k);

    let numConnectedComponents = 0;
    const visited = new Set();

    for (let node = 0; node < properties.length; node++) {
        if (visited.has(node)) continue;

        numConnectedComponents++;
        // The recursive leap of faith: trust the contract. When this
        // call returns, `node` and everything reachable from it — the
        // entire brand-new component — is in visited, so the loop can
        // never count this component again. We do not trace inside;
        // we just count it and move on.
        markComponentAsVisited(graph, node, visited);
    }

    return numConnectedComponents;
};
